// Lit un nombre, même s'il arrive en texte (« 1 250 », « 12,5 »)
function num(v) {
  if (typeof v === 'number') return v;
  if (v === undefined || v === null || v === '') return 0;
  const s = String(v).replace(/\s/g, '').replace(',', '.');
  const n = parseFloat(s.replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
}

const f = $('Formulaire de commande').first().json;
const code = String(f['Code produit'] || '').trim().toUpperCase();
const qte = num(f['Quantité']);
if (qte <= 0) throw new Error('La quantité doit être supérieure à 0.');

const produit = $input.all().map(i => i.json)
  .find(p => String(p['Code'] || '').trim().toUpperCase() === code);
if (!produit) throw new Error(`Code produit inconnu : ${code}. Vérifiez l'onglet Produits.`);

const prixVente = num(produit['Prix de vente (1 unité)']);
const prixAchat = num(produit["Prix d'achat (1 unité)"]);
const stockAvant = num(produit['Stock actuel']);
const seuil = num(produit["Seuil d'alerte"]);
const stockApres = stockAvant - qte;

return [{ json: {
  // Colonnes de l'onglet Commandes (mêmes titres, même ordre)
  'Date': $now.toFormat('yyyy-MM-dd HH:mm'),
  'Client': f['Nom du client'],
  'Téléphone': String(f['Téléphone du client']),
  'Code produit': code,
  'Produit': produit['Produit'],
  'Quantité': qte,
  'Prix unitaire': prixVente,
  'Montant': qte * prixVente,
  "Coût d'achat": qte * prixAchat,
  'Statut': 'Nouvelle',
  'Adresse': f['Adresse de livraison'] || '',
  'Note': f['Note'] || '',
  // Infos pour les alertes (pas écrites dans le tableau)
  _stockAvant: stockAvant,
  _stockApres: stockApres,
  _seuil: seuil,
  _unite: produit['Unité'] || '',
}}];

